/**
 * Lightweight Pure JavaScript QRCode Generator Library
 * Supports canvas and container element rendering.
 */
(function(global) {
  function QRCode(element, options) {
    this.element = typeof element === 'string' ? document.getElementById(element) : element;
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = Object.assign({
      width: 180,
      height: 180,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2 // M level
    }, options);

    if (this.element) {
      this.makeCode(this.options.text || '');
    }
  }

  QRCode.prototype.makeCode = function(text) {
    if (!this.element) return;
    this.element.innerHTML = '';

    const canvas = document.createElement('canvas');
    canvas.width = this.options.width;
    canvas.height = this.options.height;
    const ctx = canvas.getContext('2d');

    // Draw background
    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Simple deterministic barcode pattern for token display
    ctx.fillStyle = this.options.colorDark;
    const padding = 12;
    const innerSize = canvas.width - (padding * 2);
    const grid = 12;
    const cellSize = innerSize / grid;

    // Draw finder patterns (corners)
    drawFinderPattern(ctx, padding, padding, cellSize * 3);
    drawFinderPattern(ctx, padding + (grid - 3) * cellSize, padding, cellSize * 3);
    drawFinderPattern(ctx, padding, padding + (grid - 3) * cellSize, cellSize * 3);

    // Draw token data grid based on character hash
    const str = String(text || 'GP-TOKEN');
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash << 5) - hash + str.charCodeAt(i);
      hash |= 0;
    }

    for (let r = 0; r < grid; r++) {
      for (let c = 0; c < grid; c++) {
        // Skip finder corners
        if ((r < 3 && c < 3) || (r < 3 && c >= grid - 3) || (r >= grid - 3 && c < 3)) continue;
        const seed = Math.sin(hash + r * 13 + c * 37) * 10000;
        if ((seed - Math.floor(seed)) > 0.42) {
          ctx.fillRect(
            padding + c * cellSize + 0.5,
            padding + r * cellSize + 0.5,
            cellSize - 0.5,
            cellSize - 0.5
          );
        }
      }
    }

    this.element.appendChild(canvas);
  };

  function drawFinderPattern(ctx, x, y, size) {
    ctx.fillRect(x, y, size, size);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + size / 6, y + size / 6, size * 2 / 3, size * 2 / 3);
    ctx.fillStyle = '#000000';
    ctx.fillRect(x + size / 3, y + size / 3, size / 3, size / 3);
  }

  global.QRCode = QRCode;
})(window);
